//! Server Settings > Server Tag (module 989433 `NX`, `NR`, `N_`, `NB`, save `NJ`; preview `NY`; constants module 743981).
//!
//! `GET /guilds/{id}/profile` holds the tag, badge and colours; Save Changes sends them back with `PATCH`. Without the
//! `GUILD_TAGS` feature the form is dimmed and inert and Unlock with Boosting offers the perks dialog; the official
//! page's power-up shop is not drawn. Not drawn either: a badge recoloured to the chosen pair, and Show all badges' list.
//! Measured in `design/dom/settings/guild-tag-darker-cozy.json`; art generated by `tools/gen-tag-badges.mjs`.

use super::tag_badges::{BADGE_IDS, BADGE_SVGS, COLOR_PAIRS, PREVIEW_AVATARS};
use super::{Root, color, icon};
use crate::editor::{Editor, EditorEvent};
use crate::net::Request;
use dc_state::Id;
use gpui::{
    AnyElement, Context, Entity, FontWeight, Image, ImageFormat, IntoElement, SharedString,
    Subscription, div, img, prelude::*, px,
};
use serde_json::{Value, json};
use std::sync::Arc;

pub(super) const TAG_PREFIX: &str = "guild-tag:";
const SAVED_PREFIX: &str = "guild-tag:saved:";
/// The visible picker's badges and the first row behind Show all badges.
const VISIBLE_BADGES: usize = 10;
const LOCKED_BADGES: usize = 5;
/// `NR`: letters and numbers, at most four.
const TAG_LIMIT: usize = 4;
/// `NY`: name, its colour, the message, whether it is the one in focus.
const PREVIEW: [(&str, u32, &str, bool); 5] = [
    ("Roka", 0x7487f8, "anyone down for aram", false),
    ("hongo", 0x92dba6, "count me in", false),
    ("Lily", 0xf1a579, "check out my tag!", true),
    ("sharon", 0x7487f8, "woah how did you get that", false),
    ("Lily", 0xf1a579, "anyone here can get it!", false),
];

/// The tag's values, as saved and as edited.
#[derive(Clone, Debug, Default, PartialEq)]
pub(crate) struct TagValues {
    tag: Option<String>,
    badge: u64,
    primary: Option<String>,
    secondary: Option<String>,
}

/// `NR`'s filter: what the input keeps of what was typed.
fn clean_tag(text: &str) -> String {
    text.chars()
        .filter(char::is_ascii_alphanumeric)
        .take(TAG_LIMIT)
        .collect()
}

/// `NJ`'s body.
fn tag_body(values: &TagValues) -> Value {
    json!({
        "tag": values.tag,
        "badge": values.badge,
        "badge_color_primary": values.primary,
        "badge_color_secondary": values.secondary,
    })
}

/// The page's state.
#[derive(Default)]
pub(crate) struct TagState {
    saved: TagValues,
    now: TagValues,
    visibility: u64,
    field: Option<(Entity<Editor>, Subscription)>,
    error: Option<String>,
}

impl Root {
    fn tag_mut(&mut self) -> Option<&mut TagState> {
        self.server_settings.as_mut().map(|open| &mut open.tag)
    }

    pub(super) fn request_tag(&mut self, guild: Id) {
        use base64::Engine;
        for (index, svg) in BADGE_SVGS.iter().enumerate() {
            self.images
                .entry(format!("tag-badge:{index}"))
                .or_insert_with(|| {
                    Arc::new(Image::from_bytes(ImageFormat::Svg, svg.as_bytes().to_vec()))
                });
        }
        for (index, avatar) in PREVIEW_AVATARS.iter().enumerate() {
            if let Ok(bytes) = base64::engine::general_purpose::STANDARD.decode(avatar) {
                self.images
                    .entry(format!("tag-avatar:{index}"))
                    .or_insert_with(|| Arc::new(Image::from_bytes(ImageFormat::Png, bytes)));
            }
        }
        let _ = self.requests.send(Request::Rest {
            key: Some(format!("{TAG_PREFIX}{guild}")),
            method: reqwest::Method::GET,
            route: format!("/guilds/{guild}/profile"),
            body: None,
        });
    }

    pub(super) fn tag_fetched(&mut self, key: &str, cx: &mut Context<Self>) {
        let report = self.fetched.get(key).cloned().unwrap_or_default();
        if let Some(guild) = key.strip_prefix(SAVED_PREFIX) {
            if report["ok"] == true {
                if let Ok(guild) = guild.parse::<Id>() {
                    self.request_tag(guild);
                }
            } else if let Some(state) = self.tag_mut() {
                state.error = report["body"]["message"].as_str().map(str::to_owned);
            }
            cx.notify();
            return;
        }
        if report["ok"] != true {
            return;
        }
        let body = &report["body"];
        let text = |name: &str| body[name].as_str().map(str::to_owned);
        let values = TagValues {
            tag: text("tag"),
            badge: body["badge"].as_u64().unwrap_or(BADGE_IDS[0]),
            primary: text("badge_color_primary"),
            secondary: text("badge_color_secondary"),
        };
        let shown = values.tag.clone().unwrap_or_default();
        let field = cx.new(|cx| {
            let mut editor = Editor::new(super::editor_style(), cx);
            editor.set_placeholder("WUMP".to_owned());
            editor.set_text(&shown);
            editor
        });
        let events = cx.subscribe(&field, |this, editor, event: &EditorEvent, cx| {
            match event {
                EditorEvent::Submit(text) => {
                    let text = text.clone();
                    editor.update(cx, |editor, _| editor.set_text(&text));
                }
                EditorEvent::Edited => {
                    let text = editor.read(cx).text().to_owned();
                    let kept = clean_tag(&text);
                    if kept != text {
                        editor.update(cx, |editor, _| editor.set_text(&kept));
                    }
                    if let Some(state) = this.tag_mut() {
                        state.now.tag = Some(kept);
                    }
                }
                EditorEvent::Cancel => {}
            }
            cx.notify();
        });
        let visibility = body["visibility"].as_u64().unwrap_or(0);
        if let Some(state) = self.tag_mut() {
            state.saved = values.clone();
            state.now = values;
            state.visibility = visibility;
            state.field = Some((field, events));
            state.error = None;
        }
        cx.notify();
    }

    pub(super) fn tag_dirty(&self) -> bool {
        self.server_settings
            .as_ref()
            .is_some_and(|open| open.tag.saved != open.tag.now)
    }

    pub(super) fn reset_tag(&mut self, cx: &mut Context<Self>) {
        let mut field = None;
        if let Some(state) = self.tag_mut() {
            state.now = state.saved.clone();
            state.error = None;
            field = state
                .field
                .as_ref()
                .map(|(editor, _)| (editor.clone(), state.saved.tag.clone().unwrap_or_default()));
        }
        if let Some((editor, text)) = field {
            editor.update(cx, |editor, _| editor.set_text(&text));
        }
        cx.notify();
    }

    pub(super) fn save_tag(&mut self, guild: Id, cx: &mut Context<Self>) {
        let Some(state) = self.server_settings.as_ref().map(|open| &open.tag) else {
            return;
        };
        let body = tag_body(&state.now);
        let _ = self.requests.send(Request::Rest {
            key: Some(format!("{SAVED_PREFIX}{guild}")),
            method: reqwest::Method::PATCH,
            route: format!("/guilds/{guild}/profile"),
            body: Some(body),
        });
        cx.notify();
    }

    fn go_to_page(&mut self, page: super::server_settings::Page, cx: &mut Context<Self>) {
        if let Some(open) = self.server_settings.as_mut() {
            open.page = page;
        }
        if let Some(guild) = self.server_settings.as_ref().map(|open| open.guild) {
            self.request_server_page(guild, page, cx);
        }
        cx.notify();
    }

    fn tag_notice(body: AnyElement) -> gpui::Div {
        div()
            .p(px(8.))
            .rounded(px(4.))
            .border_1()
            .border_color(color("--inlinenotice-border-info"))
            .bg(color("--background-feedback-mod-info"))
            .flex()
            .items_center()
            .gap(px(10.))
            .child(
                div()
                    .flex_none()
                    .child(icon("tag_info", 24., "--icon-feedback-info")),
            )
            .child(
                div()
                    .flex_1()
                    .min_w(px(0.))
                    .text_size(px(12.))
                    .line_height(px(16.))
                    .font_weight(FontWeight(500.))
                    .text_color(color("--text-default"))
                    .child(body),
            )
    }

    fn tag_label(text: &'static str) -> gpui::Div {
        div()
            .text_size(px(16.))
            .line_height(px(20.))
            .font_weight(FontWeight(500.))
            .text_color(color("--text-strong"))
            .child(text)
    }

    /// `pickerItem_SMlho9`.
    fn tag_item(selected: bool, enabled: bool, id: SharedString) -> gpui::Stateful<gpui::Div> {
        div()
            .id(id)
            .size(px(64.))
            .rounded(px(4.))
            .border_1()
            .border_color(if selected {
                if enabled {
                    color("--brand-400")
                } else {
                    color("--border-strong")
                }
            } else {
                color("--border-subtle")
            })
            .bg(color("--background-mod-muted"))
            .when(enabled, |this| this.cursor_pointer())
            .flex()
            .items_center()
            .justify_center()
    }

    /// The left column's form (`c` in `NX`).
    fn tag_form(&self, enabled: bool, cx: &mut Context<Self>) -> AnyElement {
        let Some(state) = self.server_settings.as_ref().map(|open| &open.tag) else {
            return div().into_any_element();
        };
        let selected_badge = state.now.badge;
        let primary = state.now.primary.clone();
        let secondary = state.now.secondary.clone();
        let field = state.field.as_ref().map(|(editor, _)| editor.clone());
        let badge_of = |index: usize, size: f32, faded: bool| {
            self.images
                .get(&format!("tag-badge:{index}"))
                .cloned()
                .map(|picture| {
                    img(picture)
                        .size(px(size))
                        .when(faded, |this| this.opacity(0.08))
                })
        };
        let learn = self.text_with_link(
            "tag-change-learn",
            "Updating your Server Tag will require all of your members to manually reapply the tag to their profile. We do this to prevent abuse. ",
            "Learn more",
            "",
            cx,
            |_, cx| cx.open_url("https://support.discord.com/hc/en-us/articles/31444248479639"),
        );
        let mut badges = div().w(px(352.)).flex().flex_wrap().gap(px(8.));
        for (index, id) in BADGE_IDS.iter().copied().enumerate().take(VISIBLE_BADGES) {
            let selected = id == selected_badge;
            badges = badges.child(
                Self::tag_item(selected, enabled, format!("tag-badge-{index}").into())
                    .children(badge_of(index, 32., false))
                    .when(enabled, |this| {
                        this.on_click(cx.listener(move |this, _, _, cx| {
                            if let Some(state) = this.tag_mut() {
                                state.now.badge = id;
                            }
                            cx.notify();
                        }))
                    }),
            );
        }
        let mut locked = div().w(px(352.)).flex().gap(px(8.));
        for index in VISIBLE_BADGES..VISIBLE_BADGES + LOCKED_BADGES {
            locked = locked.child(
                Self::tag_item(false, false, format!("tag-badge-{index}").into())
                    .children(badge_of(index, 32., true)),
            );
        }
        let mut pairs = div().w(px(352.)).flex().flex_wrap().gap(px(8.));
        let swatches = BADGE_SVGS.len() - VISIBLE_BADGES - LOCKED_BADGES;
        for (index, (first, second)) in COLOR_PAIRS.iter().copied().enumerate().take(swatches) {
            let selected =
                primary.as_deref() == Some(first) && secondary.as_deref() == Some(second);
            pairs = pairs.child(
                Self::tag_item(selected, enabled, format!("tag-color-{index}").into())
                    .children(badge_of(index + VISIBLE_BADGES + LOCKED_BADGES, 32., false))
                    .when(enabled, |this| {
                        this.on_click(cx.listener(move |this, _, _, cx| {
                            if let Some(state) = this.tag_mut() {
                                state.now.primary = Some(first.to_owned());
                                state.now.secondary = Some(second.to_owned());
                            }
                            cx.notify();
                        }))
                    }),
            );
        }
        div()
            .when(!enabled, |this| this.opacity(0.3))
            .child(
                div()
                    .mb(px(40.))
                    .child(Self::tag_label("Choose Name").mb(px(8.)))
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .child(
                                div()
                                    .w(px(166.))
                                    .h(px(70.))
                                    .flex_none()
                                    .rounded(px(4.))
                                    .border_1()
                                    .border_color(color("--border-subtle"))
                                    .bg(color("--background-base-lowest"))
                                    .pl(px(16.))
                                    .flex()
                                    .items_center()
                                    .children(badge_of(1, 40., false))
                                    .child(
                                        div()
                                            .ml(px(8.))
                                            .w(px(84.))
                                            .text_size(px(24.))
                                            .text_color(color("--text-default"))
                                            .children(field),
                                    ),
                            )
                            .child(
                                div()
                                    .ml(px(12.))
                                    .w(px(154.))
                                    .text_size(px(12.))
                                    .line_height(px(16.))
                                    .font_weight(FontWeight(500.))
                                    .text_color(color("--text-muted"))
                                    .child("You may use max 4 characters, alphabet and numbers."),
                            ),
                    )
                    .child(div().mt(px(12.)).child(Self::tag_notice(learn))),
            )
            .child(
                div()
                    .mb(px(40.))
                    .child(Self::tag_label("Choose Badge"))
                    .child(
                        div()
                            .mt(px(4.))
                            .mb(px(8.))
                            .text_size(px(14.))
                            .line_height(px(18.))
                            .text_color(color("--text-subtle"))
                            .child(
                                "Changing just the badge won't remove the Server Tag from members.",
                            ),
                    )
                    .child(badges)
                    .child(
                        div().mt(px(8.)).relative().h(px(64.)).child(locked).child(
                            div()
                                .absolute()
                                .top(px(22.))
                                .left(px(0.))
                                .w(px(352.))
                                .flex()
                                .justify_center()
                                .text_size(px(14.))
                                .line_height(px(18.))
                                .font_weight(FontWeight(600.))
                                .text_color(color("--text-subtle"))
                                .child("Show all badges"),
                        ),
                    ),
            )
            .child(
                div()
                    .child(Self::tag_label("Choose Color").mb(px(8.)))
                    .child(pairs),
            )
            .into_any_element()
    }

    /// `NY`.
    fn tag_preview(&self) -> AnyElement {
        let rows: Vec<AnyElement> = PREVIEW
            .iter()
            .enumerate()
            .map(|(index, (name, tint, text, focused))| {
                let avatar = self.images.get(&format!("tag-avatar:{index}")).cloned();
                let badge = self.images.get("tag-badge:1").cloned();
                div()
                    .h(px(40.))
                    .flex()
                    .when(!*focused, |this| this.opacity(0.2))
                    .child(
                        div()
                            .size(px(40.))
                            .mr(px(12.))
                            .flex_none()
                            .rounded_full()
                            .children(
                                avatar.map(|avatar| img(avatar).size(px(40.)).rounded_full()),
                            ),
                    )
                    .child(
                        div()
                            .flex()
                            .flex_col()
                            .child(
                                div()
                                    .h(px(20.))
                                    .flex()
                                    .items_center()
                                    .child(
                                        div()
                                            .text_size(px(16.))
                                            .line_height(px(20.))
                                            .font_weight(FontWeight(500.))
                                            .text_color(gpui::rgb(*tint))
                                            .child(*name),
                                    )
                                    .when(*focused, |this| {
                                        this.child(
                                            div()
                                                .ml(px(4.))
                                                .h(px(20.))
                                                .px(px(4.))
                                                .rounded(px(4.))
                                                .bg(color("--background-mod-normal"))
                                                .flex()
                                                .items_center()
                                                .gap(px(4.))
                                                .children(
                                                    badge.map(|badge| img(badge).size(px(12.))),
                                                )
                                                .child(
                                                    div()
                                                        .text_size(px(12.))
                                                        .line_height(px(16.))
                                                        .font_weight(FontWeight(600.))
                                                        .text_color(color("--text-strong"))
                                                        .child("WUMP"),
                                                ),
                                        )
                                    }),
                            )
                            .child(
                                div()
                                    .text_size(px(16.))
                                    .line_height(px(20.))
                                    .text_color(color("--text-strong"))
                                    .child(*text),
                            ),
                    )
                    .into_any_element()
            })
            .collect();
        div()
            .w(px(288.))
            .h(px(272.))
            .flex_none()
            .p(px(12.))
            .rounded(px(4.))
            .bg(color("--background-base-lowest"))
            .flex()
            .flex_col()
            .gap(px(12.))
            .children(rows)
            .into_any_element()
    }

    /// The page (`NX`).
    pub(super) fn server_tag_page(&self, guild: Id, cx: &mut Context<Self>) -> AnyElement {
        let Some(state) = self.server_settings.as_ref().map(|open| &open.tag) else {
            return div().into_any_element();
        };
        let has_tags = self
            .stores
            .guild(guild)
            .is_some_and(|known| known.features.iter().any(|feature| feature == "GUILD_TAGS"));
        let turned_on = state.now.tag.is_some();
        let enabled = has_tags && turned_on;
        // `Nf.i.VISIBLE`: public, and public while recruiting.
        let public = matches!(state.visibility, 1 | 3);
        let error = state.error.clone();
        use super::server_settings::Page;
        // Two links in one sentence: each opens its page.
        let before = "Create a tag that your server members can display next to their name! Anyone outside your server can view your ";
        let first = "Server Profile";
        let middle = " through the Server Tag, and if applications are enabled, they can ";
        let second = "apply to join";
        let text = format!("{before}{first}{middle}{second}.");
        let first_range = before.len()..before.len() + first.len();
        let second_start = first_range.end + middle.len();
        let second_range = second_start..second_start + second.len();
        let link = gpui::HighlightStyle {
            color: Some(color("--text-link").into()),
            ..Default::default()
        };
        let root = cx.entity().downgrade();
        let description = gpui::InteractiveText::new(
            "tag-description",
            gpui::StyledText::new(text)
                .with_highlights([(first_range.clone(), link), (second_range.clone(), link)]),
        )
        .on_click(vec![first_range, second_range], move |at, _, cx| {
            let _ = root.update(cx, |this, cx| {
                this.go_to_page(if at == 0 { Page::Profile } else { Page::Access }, cx);
            });
        });
        let edit_setting = self.text_with_link(
            "tag-edit-setting",
            "Your Server Profile is private. Users will not be able to see it from a Server Tag. ",
            "Edit Setting",
            "",
            cx,
            |this, cx| this.go_to_page(Page::Profile, cx),
        );
        let top_control: AnyElement = if has_tags {
            div()
                .p(px(12.))
                .rounded(px(4.))
                .bg(color("--background-base-lower"))
                .flex()
                .items_center()
                .justify_between()
                .child(
                    div()
                        .text_size(px(16.))
                        .line_height(px(20.))
                        .font_weight(FontWeight(600.))
                        .text_color(color("--text-strong"))
                        .child("Enable Server Tag"),
                )
                .child(
                    div()
                        .id("tag-enable")
                        .cursor_pointer()
                        .child(super::create_channel::switch(turned_on))
                        .on_click(cx.listener(|this, _, _, cx| {
                            if let Some(state) = this.tag_mut() {
                                state.now.tag = if state.now.tag.is_some() {
                                    None
                                } else {
                                    Some(String::new())
                                };
                            }
                            cx.notify();
                        })),
                )
                .into_any_element()
        } else {
            div()
                .id("tag-unlock")
                .w(px(202.))
                .h(px(40.))
                .pl(px(16.))
                .rounded(px(8.))
                .bg(gpui::rgb(0xffffff))
                .shadow(vec![gpui::BoxShadow {
                    color: gpui::hsla(250. / 360., 0.9, 0.7, 0.45),
                    offset: gpui::point(px(0.), px(0.)),
                    blur_radius: px(14.),
                    spread_radius: px(0.),
                    inset: false,
                }])
                .cursor_pointer()
                .flex()
                .items_center()
                .gap(px(4.))
                .child(
                    gpui::svg()
                        .path("icons/boost_gem.svg")
                        .size(px(20.))
                        .text_color(gpui::rgb(0x000000)),
                )
                .child(
                    div()
                        .text_size(px(16.))
                        .line_height(px(20.))
                        .font_weight(FontWeight(500.))
                        .text_color(gpui::rgb(0x000000))
                        .child("Unlock with Boosting"),
                )
                .on_click(cx.listener(|this, _, _, cx| {
                    this.open_perks(super::server_boost::Perks::Vanity, cx);
                }))
                .into_any_element()
        };
        div()
            .flex()
            .flex_col()
            .child(
                div()
                    .mb(px(24.))
                    .text_size(px(20.))
                    .line_height(px(24.))
                    .font_weight(FontWeight(600.))
                    .text_color(color("--text-strong"))
                    .child("Server Tag"),
            )
            .child(
                div()
                    .flex()
                    .child(
                        div()
                            .w(px(332.))
                            .flex_none()
                            .mr(px(40.))
                            .child(
                                div()
                                    .mb(px(24.))
                                    .child(
                                        div()
                                            .text_size(px(14.))
                                            .line_height(px(18.))
                                            .font_weight(FontWeight(500.))
                                            .text_color(color("--text-subtle"))
                                            .child(description),
                                    )
                                    .when(!public, |this| {
                                        this.child(
                                            div().mt(px(16.)).child(Self::tag_notice(edit_setting)),
                                        )
                                    }),
                            )
                            .child(div().mb(px(8.)).child(top_control))
                            .child(self.tag_form(enabled, cx))
                            .children(error.map(|error| {
                                div()
                                    .mt(px(12.))
                                    .text_size(px(14.))
                                    .line_height(px(18.))
                                    .text_color(color("--text-feedback-critical"))
                                    .child(error)
                            })),
                    )
                    .child(self.tag_preview()),
            )
            .into_any_element()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_tag_keeps_four_letters_or_numbers() {
        assert_eq!(clean_tag("wu mp!9"), "wump");
        assert_eq!(clean_tag("A1"), "A1");
    }

    #[test]
    fn saving_sends_the_profiles_fields() {
        let values = TagValues {
            tag: Some("WUMP".to_owned()),
            badge: 6,
            primary: Some("#ff1c90".to_owned()),
            secondary: Some("#ff7fc0".to_owned()),
        };
        assert_eq!(
            tag_body(&values),
            json!({
                "tag": "WUMP",
                "badge": 6,
                "badge_color_primary": "#ff1c90",
                "badge_color_secondary": "#ff7fc0",
            })
        );
    }

    #[test]
    fn the_art_counts_match_the_page() {
        assert_eq!(BADGE_IDS.len(), VISIBLE_BADGES);
        assert_eq!(
            BADGE_SVGS.len(),
            VISIBLE_BADGES + LOCKED_BADGES + COLOR_PAIRS.len()
        );
        assert_eq!(PREVIEW_AVATARS.len(), PREVIEW.len());
    }
}
